  async function loadEditions(format,language){const key=format+":"+language;if(state.editions?.[key])return state.editions[key];state.editions=state.editions||{};state.editions[key]=await get(`${API.quran}/edition?format=${encodeURIComponent(format)}&language=${encodeURIComponent(language)}`);return state.editions[key]}
