  async function loadCalendar(){const target=document.getElementById("calendar-content");if(!target)return;const request=++calendarSequence,c=city(),place=c.label,d=new Date(),date=`${String(d.getDate()).padStart(2,"0")}-${String(d.getMonth()+1).padStart(2,"0")}-${d.getFullYear()}`;try{const data=await get(`${API.aladhan}/timingsByCity/${date}?city=${encodeURIComponent(c.id)}&country=${encodeURIComponent(c.country)}&method=${methodId()}`);if(!target.isConnected||request!==calendarSequence)return;const h=data.date?.hijri||{},g=data.date?.gregorian||{},t=data.timings||{},offset=Number(localStorage.getItem(K.offset)||0),prayers=[["الفجر","Fajr"],["الشروق","Sunrise"],["الظهر","Dhuhr"],["العصر","Asr"],["المغرب","Maghrib"],["العشاء","Isha"]],methodName=data.meta?.method?.name||METHODS.find(m=>m.id===methodId())?.label||"طريقة غير محددة";let day=Number(h.day),month=h.month?.ar||h.month?.en||"",year=digits(h.year||"");if(offset){try{const dt=new Date(Date.UTC(Number(g.year),Number(g.month?.number)-1,Number(g.day)+offset,12)),parts=new Intl.DateTimeFormat("ar-SA-u-ca-islamic-umalqura",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"}).format(dt);day=null;month=parts;year=""}catch{day=Number(h.day)}}const hijri=day===null?esc(month):`${digits(day)} ${esc(month)} ${year}`,holidayMarkup=!offset&&Array.isArray(h.holidays)&&h.holidays.length?`<section class="section card"><div class="section-head"><div><h2>مناسبات حسب بيانات المصدر</h2><p>للتحقق من تاريخ الرؤية محلياً.</p></div></div><div class="grid grid-3">${h.holidays.map(name=>`<div class="quick-metric">${esc(name)}</div>`).join("")}</div></section>`:"";target.innerHTML=`<div class="calendar-panel"><article class="date-card"><span class="eyebrow">${esc(place)}</span><strong>${hijri}</strong><p>${esc(g.weekday?.ar||g.weekday?.en||"")} · ${digits(g.day||"")} ${esc(g.month?.ar||g.month?.en||"")} ${digits(g.year||"")}</p><small>${offset?`تاريخ محسوب محلياً بفارق ${offset>0?"+":"−"}${digits(Math.abs(offset))} يوم`:"التاريخ الهجري حسب بيانات المصدر"}</small><small>طريقة الحساب: ${esc(methodName)}</small></article><div class="card"><span class="eyebrow">مواقيت اليوم</span><h2>${esc(place)}</h2><div class="prayer-grid">${prayers.map(([name,key])=>`<div class="prayer-time"><small>${name}</small><strong>${esc(String(t[key]||"—").split(" ")[0])}</strong></div>`).join("")}</div></div></div>${holidayMarkup}`}catch{if(target?.isConnected&&request===calendarSequence)target.innerHTML=`<div class="empty-state"><strong>تعذر جلب التقويم</strong><span>تحقق من المدينة والاتصال بالإنترنت.</span><p><a class="button" href="https://aladhan.com/prayer-times-api" target="_blank" rel="noopener noreferrer">توثيق AlAdhan ↗</a></p></div>`}}
  function syncOffset(){const el=document.getElementById("hijri-offset");if(el)el.value=localStorage.getItem(K.offset)||"0"}
  async function loadJuz(id){state.currentChapter=null;try{const data=await get(`${API.quran}/juz/${encodeURIComponent(id)}`);if(current().page!=="juz"||current().id!==Number(id))return;const rows=data.ayahs||[];let prior=0;const html=rows.map(a=>{const s=a.surah?.number||a.surahNumber,n=a.numberInSurah,key=`${s}:${n}`,name=a.surah?.name||`السورة ${digits(s)}`;let start="";if(prior!==s){prior=s;start=`<h2 style="color:var(--green);margin:26px 0 8px">${esc(name)}</h2>`}const mark=isSaved(key);return `${start}<span class="ayah" data-ayah-key="${esc(key)}" data-ayah-name="${esc(name)}">${esc(a.text)}<span class="ayah-number">${digits(n)}</span><span class="ayah-actions"><button type="button" data-action="save-ayah" data-key="${esc(key)}" aria-label="${mark?"إزالة":"إضافة"} الآية إلى المحفوظات">${mark?"♥":"♡"}</button><button type="button" data-action="copy-ayah" data-key="${esc(key)}" data-text="${esc(a.text)}" aria-label="نسخ الآية">⧉</button></span></span>`}).join(" ");app.innerHTML=`${heading(`الجزء ${digits(id)}`,`${digits(rows.length)} آية · النص من Al Quran Cloud`,`<a class="button secondary" href="${route("quran")}">فهرس السور</a>`)}<article class="reader-paper"><div class="reader-source">النص معروض كما ورد من المصدر.</div><div class="ayah-flow" lang="ar" dir="rtl">${html}</div><div class="chapter-switch">${id>1?`<a class="button secondary small" href="${route(`juz/${id-1}`)}">الجزء السابق ←</a>`:"<span></span>"}${id<30?`<a class="button secondary small" href="${route(`juz/${id+1}`)}">الجزء التالي ←</a>`:"<span></span>"}</div></article><p class="source-note">المصدر: ${link("https://alquran.cloud/api","Al Quran Cloud API")}</p>`}catch{if(current().page==="juz")app.innerHTML=`<div class="empty-state"><strong>تعذر تحميل الجزء</strong><p>${link("https://alquran.cloud/api","راجع مصدر النص")}</p><p><a class="button" href="${route("quran")}">العودة إلى فهرس السور</a></p></div>`}}
  async function loadIndexedCollection(kind,id){const specs={hizb:{max:60,title:n=>`الحزب ${digits(n)}`,endpoint:"hizbQuarter"},rub:{max:240,title:n=>`ربع الحزب ${digits(n)}`,endpoint:"hizbQuarter"},page:{max:604,title:n=>`صفحة المصحف ${digits(n)}`,endpoint:"page"}};const spec=specs[kind];if(!spec||id<1||id>spec.max){app.innerHTML=`<div class="empty-state"><strong>رقم الفهرس غير صالح</strong><p><a class="button" href="${route("quran")}">العودة إلى فهرس القرآن</a></p></div>`;return}try{let rows=[];if(kind==="hizb"){const first=(id-1)*4+1,parts=await Promise.all(Array.from({length:4},(_,i)=>get(`${API.quran}/hizbQuarter/${first+i}`)));rows=parts.flatMap(x=>x.ayahs||[])}else{const data=await get(`${API.quran}/${spec.endpoint}/${encodeURIComponent(id)}`);rows=data.ayahs||[]}if(current().page!==kind||current().id!==Number(id))return;if(!rows.length)throw Error("No verses");let prior=0;const content=rows.map(a=>{const surah=Number(a.surah?.number||a.surahNumber||a.chapter?.number||0),ayah=Number(a.numberInSurah||a.verseNumber||0),name=a.surah?.name||a.surahName||`السورة ${digits(surah)}`,key=`${surah}:${ayah}`;let head="";if(surah!==prior){prior=surah;head=`<h2 class="collection-surah-heading">${esc(name)}</h2>`}return `${head}<span class="ayah" data-ayah-key="${esc(key)}" data-ayah-name="${esc(name)}">${esc(a.text||"")}<span class="ayah-number" aria-label="الآية ${digits(ayah)}">${digits(ayah)}</span><span class="ayah-actions"><button type="button" data-action="save-ayah" data-key="${esc(key)}" aria-label="إضافة الآية إلى المحفوظات">♡</button><button type="button" data-action="copy-ayah" data-key="${esc(key)}" data-text="${esc(a.text||"")}" aria-label="نسخ الآية">⧉</button><button type="button" data-action="play-ayah" data-key="${esc(key)}" aria-label="استمع إلى الآية">▶</button><a href="https://corpus.quran.com/translation.jsp?chapter=${surah}&amp;verse=${ayah}" target="_blank" rel="noopener noreferrer" aria-label="تحليل كلمات الآية في Quranic Arabic Corpus">◈</a></span></span>`}).join(" ");const previous=id>1?`<a class="button secondary small" href="${route(`${kind}/${id-1}`)}">السابق ←</a>`:"<span></span>",next=id<spec.max?`<a class="button secondary small" href="${route(`${kind}/${id+1}`)}">التالي ←</a>`:"<span></span>";app.innerHTML=`${heading(spec.title(id),`${digits(rows.length)} آية · النص من Al Quran Cloud`,`<a class="button secondary" href="${route("quran")}">فهرس القرآن</a>`)}<article class="reader-paper"><div class="reader-source">يُعرض النص كما يرد من المصدر، مع فهرسة ${kind==="hizb"?"الحزب":kind==="rub"?"ربع الحزب":"صفحة مصحف المدينة"}.</div><div class="ayah-flow" lang="ar" dir="rtl">${content}</div><div class="chapter-switch">${previous}${next}</div></article><p class="source-note">المصدر: ${link("https://alquran.cloud/api","Al Quran Cloud API")}</p>`}catch{if(current().page===kind)app.innerHTML=`<div class="empty-state"><strong>تعذر تحميل هذا الموضع</strong><span>تحقق من الرقم أو اتصال الإنترنت.</span><p><a class="button" href="${route("quran")}">العودة إلى فهرس القرآن</a></p></div>`}}

  async function saveAyah(key){const [s,a]=key.split(":").map(Number),items=saved(),index=items.findIndex(x=>x.key===key);if(index>=0){items.splice(index,1);write(K.saved,items);toast("أزيلت الآية من المحفوظات.");const b=app.querySelector(`[data-action="save-ayah"][data-key="${CSS.escape(key)}"]`);if(b){b.textContent="♡";b.setAttribute("aria-label","إضافة الآية إلى المحفوظات")}return}let text="",name="";if(state.currentChapter?.number===s){const verse=state.currentChapter.ayahs?.find(x=>x.numberInSurah===a);text=verse?.text||"";name=state.currentChapter.name||""}else{try{const c=await getChapter(s),verse=c.ayahs?.find(x=>x.numberInSurah===a);text=verse?.text||"";name=c.name||""}catch{toast("تعذر الحفظ لأن النص غير متاح من المصدر.");return}}if(!text){toast("لم يصل نص موثق لهذه الآية من المصدر.");return}write(K.saved,[...items,{key,surah:s,ayah:a,text,surahName:name}]);write(K.last,{surah:s,ayah:a,surahName:name});toast("حُفظت الآية على هذا الجهاز.");const b=app.querySelector(`[data-action="save-ayah"][data-key="${CSS.escape(key)}"]`);if(b){b.textContent="♥";b.setAttribute("aria-label","إزالة الآية من المحفوظات")}}
  async function copyText(text){try{await navigator.clipboard.writeText(text);toast("تم النسخ.")}catch{toast("تعذر النسخ تلقائياً؛ حدّد النص وانسخه يدوياً.")}}
  function favoriteSurahPanel(){const items=read(K.favorites,[]);return `<section class="section card"><div class="section-head"><div><h2>السور المفضلة</h2><p>قائمة محلية لفتح السور بسرعة.</p></div></div>${items.length?`<div class="favorite-surah-list">${items.map(x=>`<div class="favorite-surah-row"><a href="${route(`reader/${x.id}`)}">${esc(x.name||`السورة ${digits(x.id)}`)} · ${digits(x.id)}</a><button class="button ghost small" data-action="toggle-surah" data-surah="${Number(x.id)}" data-name="${esc(x.name||"")}">إزالة</button></div>`).join("")}</div>`:`<p class="muted">لم تحفظ سوراً بعد؛ أضفها من شريط أدوات القارئ.</p>`}</section>`}
  function studyPanel(){const progress=read(K.study,{}),today=dateKey(),done=progress.date===today?Number(progress.count||0):0,target=Number(localStorage.getItem(K.dailyTarget)||3),days=progress.days||{},week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));const key=dateKey(d);return{key,label:new Intl.DateTimeFormat("ar",{weekday:"short"}).format(d),count:Number(days[key]||0)}}),streak=(()=>{let n=0;for(let i=0;i<7;i++){const d=new Date();d.setDate(d.getDate()-i);if(Number(days[dateKey(d)]||0)>0)n++;else if(i>0)break}return n})(),scheduled=reviewItems(),dueReviews=Object.values(scheduled).filter(x=>!x.due||x.due<=today),badges=studyAchievements(progress,streak);return `<section class="section card study-panel"><div class="section-head"><div><h2>خطة الحفظ والمراجعة</h2><p>تقدمك محفوظ في هذا المتصفح فقط.</p></div><label>هدف اليوم<select id="daily-target" class="select-field"><option value="1" ${target===1?"selected":""}>آية واحدة</option><option value="3" ${target===3?"selected":""}>٣ آيات</option><option value="5" ${target===5?"selected":""}>٥ آيات</option><option value="10" ${target===10?"selected":""}>١٠ آيات</option></select></label></div><div class="study-summary"><div><strong>${digits(done)} / ${digits(target)}</strong><small>إنجاز اليوم</small></div><div><strong>${digits(progress.total||0)}</strong><small>إجمالي جلسات المراجعة</small></div><div><strong>${digits(streak)}</strong><small>أيام متتابعة في آخر أسبوع</small></div></div><div class="study-progress"><span style="width:${Math.min(100,done/target*100)}%"></span></div><div class="week-progress">${week.map(x=>`<div title="${digits(x.count)} جلسة"><span style="height:${Math.max(5,Math.min(100,x.count*14))}%"></span><small>${esc(x.label)}</small></div>`).join("")}</div><section class="review-schedule"><div class="section-head"><div><h3>قائمة المراجعة المجدولة</h3><p>${digits(dueReviews.length)} مستحقة اليوم · ${digits(Object.keys(scheduled).length)} إجمالي الآيات</p></div></div>${dueReviews.length?dueReviews.slice(0,30).map(item=>`<article class="review-due-row"><div><strong>${esc(item.surahName||`السورة ${digits(item.surah)}`)} · ${digits(item.ayah)}</strong><p dir="rtl">${esc(item.text)}</p><a href="${route(`reader/${item.surah}?ayah=${item.ayah}`)}">افتح في المصحف ←</a></div><div class="review-ratings"><button class="button small ghost" data-action="rate-review" data-key="${esc(item.key)}" data-rating="again">أعد</button><button class="button small secondary" data-action="rate-review" data-key="${esc(item.key)}" data-rating="hard">صعب</button><button class="button small secondary" data-action="rate-review" data-key="${esc(item.key)}" data-rating="good">جيد</button><button class="button small" data-action="rate-review" data-key="${esc(item.key)}" data-rating="easy">سهل</button></div></article>`).join(""):`<p class="muted">لا توجد آيات مستحقة اليوم. أضف آية من القارئ أو المحفوظات.</p>`}</section><div class="achievement-list">${badges.length?badges.map(label=>`<span class="achievement-badge">✦ ${esc(label)}</span>`).join(""):`<span class="muted">ستظهر شارات التقدم مع استمرار الحفظ والمراجعة.</span>`}</div><div class="heading-actions"><button class="button" data-action="study-complete">سجل جلسة مراجعة</button><button class="button secondary" data-action="start-quiz">اختبر حفظي</button><a class="button ghost" href="${route("quran")}">افتح المصحف</a></div><div id="quiz-area" aria-live="polite"></div><div class="simple-mode-row"><label for="simple-mode">وضع الأطفال المبسّط</label><input id="simple-mode" type="checkbox" ${localStorage.getItem(K.simple)==="true"?"checked":""}><span class="muted">تبقي المصحف والتلاوات والأذكار ظاهرة وتخفي الأقسام المتقدمة.</span></div><p class="source-note">لا يوجد تسجيل دخول أو مزامنة سحابية في نسخة GitHub Pages؛ لا تُرسل بيانات الحفظ إلى خادم.</p></section>`}
  function toggleSurah(id,name){const list=read(K.favorites,[]),index=list.findIndex(x=>Number(x.id)===Number(id));if(index>=0){list.splice(index,1);toast("أزيلت السورة من المفضلة.")}else{list.push({id:Number(id),name:String(name||"سورة").slice(0,100)});toast("حُفظت السورة في المفضلة على هذا الجهاز.")}write(K.favorites,list);if(current().page==="reader"){const b=document.querySelector(`[data-action="toggle-surah"][data-surah="${id}"]`);if(b)b.textContent=index>=0?"♡ احفظ السورة":"♥ سورة محفوظة"}else render()}
  async function saveSurahOffline(id){const list=read(K.offline,[]);if(list.includes(Number(id))){await cacheDelete("surah-"+id);write(K.offline,list.filter(n=>Number(n)!==Number(id)));toast("أزيلت نسخة السورة المحفوظة محلياً.");const b=document.querySelector(`[data-action="offline-surah"][data-surah="${id}"]`);if(b)b.textContent="حفظ السورة دون اتصال";return}if(!state.currentChapter||Number(state.currentChapter.number)!==Number(id)){toast("افتح السورة أولاً حتى يتم حفظ بياناتها.");return}const ok=await cachePut("surah-"+id,state.currentChapter);if(!ok){toast("تعذر حفظ السورة في التخزين المحلي.");return}write(K.offline,[...list,Number(id)]);toast("حُفظت بيانات السورة لهذا الجهاز للقراءة دون اتصال.");const b=document.querySelector(`[data-action="offline-surah"][data-surah="${id}"]`);if(b)b.textContent="✓ محفوظة دون اتصال"}
  async function cacheAyahAudio(key){const match=String(key||"").match(/^(\d{1,3}):(\d{1,3})$/);if(!match){toast("رقم الآية غير صالح.");return}const surah=Number(match[1]),ayah=Number(match[2]);let chapter=state.currentChapter;if(!chapter||Number(chapter.number)!==surah){try{chapter=await getChapter(surah)}catch{toast("تعذر تحميل بيانات السورة.");return}}const verse=chapter.ayahs?.find(x=>Number(x.numberInSurah)===ayah);if(!verse?.number){toast("لم يتوفر رابط صوت موثق لهذه الآية.");return}const edition=document.getElementById("ayah-audio-edition")?.value||localStorage.getItem(K.edition)||"ar.alafasy",src=`https://cdn.islamic.network/quran/audio/128/${encodeURIComponent(edition)}/${encodeURIComponent(verse.number)}.mp3`,cacheKey="audio:"+src;if(await cacheGet(cacheKey)){toast("صوت هذه الآية محفوظ بالفعل على هذا الجهاز.");return}if(read(K.audioCacheIndex,[]).length>=200){toast("بلغت حد ٢٠٠ آية صوتية محفوظة؛ امسح بعض الملفات من صفحة المحفوظات أولاً.");return}try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000),response=await fetch(src,{signal:controller.signal});clearTimeout(timer);if(!response.ok)throw Error("Audio request failed");const blob=await response.blob();if(!blob.size||blob.size>12*1024*1024||(!blob.type.startsWith("audio/")&&blob.type!=="application/octet-stream")){toast("حجم الملف أو نوعه غير مناسب للحفظ.");return}if(navigator.storage?.estimate){const estimate=await navigator.storage.estimate();if(Number.isFinite(estimate.quota)&&Number(estimate.usage||0)+blob.size>estimate.quota*.9){toast("مساحة الجهاز المتاحة لا تكفي لحفظ الصوت.");return}}if(!await cachePut(cacheKey,blob)){toast("تعذر حفظ الصوت على هذا الجهاز.");return}const index=read(K.audioCacheIndex,[]);if(index.length>=200&&!index.includes(cacheKey)){await cacheDelete(cacheKey);toast("وصلت إلى حد الملفات الصوتية المحفوظة؛ امسح بعض الملفات ثم أعد المحاولة.");return}if(!index.includes(cacheKey))write(K.audioCacheIndex,[...index,cacheKey]);toast("حُفظ صوت الآية على هذا الجهاز للاستماع دون اتصال.")}catch{toast("تعذر تنزيل الصوت؛ تحقق من الاتصال ومصدر التلاوة.")}}
  async function clearOfflineAudio(){const keys=read(K.audioCacheIndex,[]).filter(key=>typeof key==="string"&&key.startsWith("audio:https://cdn.islamic.network/"));if(!keys.length){toast("لا توجد تلاوات محفوظة للمسح.");return}if(!confirm(`هل تريد مسح ${digits(keys.length)} ملف صوتي محفوظ من هذا الجهاز؟`))return;await Promise.all(keys.map(cacheDelete));write(K.audioCacheIndex,[]);if(audioObjectUrl){URL.revokeObjectURL(audioObjectUrl);audioObjectUrl=null}toast("تم مسح التلاوات المحفوظة دون اتصال.");render()}

