  function setMediaSession(title,sub){if(!("mediaSession"in navigator))return;try{navigator.mediaSession.metadata=new MediaMetadata({title:title||"تلاوة قرآنية",artist:sub||"بوابة القرآن",album:"Quran Portal"});const handlers={play:()=>audio.play().catch(()=>{}),pause:()=>audio.pause(),stop:()=>{audio.pause();audio.currentTime=0;state.audioQueue=null},seekbackward:e=>{audio.currentTime=Math.max(0,audio.currentTime-(e.seekOffset||10))},seekforward:e=>{audio.currentTime=Math.min(audio.duration||Infinity,audio.currentTime+(e.seekOffset||10))}};for(const [action,handler] of Object.entries(handlers))try{navigator.mediaSession.setActionHandler(action,handler)}catch{}}catch{}}
