  function search(query){const raw=query.trim(),q=normaliseSearch(raw);clearTimeout(searchTimer);const request=++searchSequence;if(!raw){searchResults.innerHTML="<p class=\"muted\">اكتب اسم قسم أو سورة لعرض النتائج.</p>";quranSearchResults.innerHTML="<p class=\"muted\">اكتب ثلاث حروف أو أكثر للبحث في الآيات.</p>";return}const rows=ROUTES.filter(x=>normaliseSearch(x[1]+" "+x[3]).includes(q)).map(x=>({name:x[1],hint:x[3],href:route(x[0])}));const ref=raw.replace(/[٠-٩]/g,d=>String("٠١٢٣٤٥٦٧٨٩".indexOf(d))).match(/^(\d{1,3})[:/](\d{1,3})$/);if(ref&&Number(ref[1])<=114&&Number(ref[2])<=286)rows.unshift({name:`السورة ${digits(ref[1])} · الآية ${digits(ref[2])}`,hint:"انتقال مباشر إلى موضع الآية",href:route(`reader/${Number(ref[1])}?ayah=${Number(ref[2])}`)});if(state.chapters){for(const x of state.chapters){if(normaliseSearch(x.name+" "+x.englishName+" "+x.englishNameTranslation).includes(q))rows.push({name:x.name,hint:"سورة "+digits(x.number)+" · "+digits(x.numberOfAyahs)+" آية",href:route("reader/"+x.number)});if(rows.length>=14)break}}searchResults.innerHTML=rows.length?rows.slice(0,15).map(x=>"<a class=\"search-result\" href=\""+esc(x.href)+"\"><span>"+esc(x.name)+"</span><small class=\"muted\">"+esc(x.hint)+"</small></a>").join(""):"<p class=\"muted\">لا توجد نتائج مطابقة في الأقسام أو الفهرس المحمّل.</p>";if(q.length<3){quranSearchResults.innerHTML="<p class=\"muted\">اكتب ثلاث حروف أو أكثر للبحث في الآيات.</p>";return}quranSearchResults.innerHTML="<p class=\"muted\">جارٍ البحث في نص القرآن…</p>";searchTimer=setTimeout(()=>searchQuran(normaliseSearch(raw),request),450)}
  async function searchQuran(query,request){try{const data=await get(API.quran+"/search/"+encodeURIComponent(query)+"/all/quran-uthmani");if(request!==searchSequence)return;const matches=Array.isArray(data.matches)?data.matches:[],rows=matches.slice(0,10).map(x=>{const surah=Number(x.surah?.number),ayah=Number(x.numberInSurah);if(!surah||!ayah)return"";const name=x.surah?.name||("السورة "+digits(surah)),href=route("reader/"+surah+"?ayah="+ayah);return"<a class=\"search-result search-verse\" href=\""+esc(href)+"\"><strong>"+esc(name)+" · الآية "+digits(ayah)+"</strong><small>"+esc(x.text||"")+"</small></a>"}).filter(Boolean);quranSearchResults.innerHTML=rows.length?rows.join(""):"<p class=\"muted\">لا توجد آيات مطابقة في المصدر.</p>"}catch{if(request===searchSequence)quranSearchResults.innerHTML="<p class=\"muted\">تعذر البحث الآن؛ تحقق من الاتصال أو جرّب لاحقاً.</p>"}}
